('','webform.webform.quiz_ash1','a:21:{s:4:\"uuid\";s:36:\"8d82137c-f0f6-4b62-99cd-8151b7590be2\";s:8:\"langcode\";s:2:\"en\";s:6:\"status\";s:4:\"open\";s:12:\"dependencies\";a:1:{s:6:\"module\";a:1:{i:0;s:10:\"vaxia_core\";}}s:6:\"weight\";i:0;s:4:\"open\";N;s:5:\"close\";N;s:3:\"uid\";i:0;s:8:\"template\";b:0;s:7:\"archive\";b:0;s:2:\"id\";s:9:\"quiz_ash1\";s:5:\"title\";s:33:\"ASH Test 1 - Story Hosting Basics\";s:11:\"description\";N;s:10:\"categories\";a:0:{}s:8:\"elements\";s:4033:\"question_1:\n  \'#title\': \'Which of the following best describes an SH?\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'A judge\'\n    a2: \'A friend\'\n    a3: \'A guide\'\n    a4: \'A boss\'\n    a5: \'An opponent\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_2:\n  \'#title\': \'Which of the following is considered a session?\'\n  \'#type\': checkboxes\n  \'#options\':\n    a1: \'Four friends work to put out a fire in the forest\'\n    a2: \'A mage researches water magic techniques at the library\'\n    a3: \'A blacksmith fashions a new sword from expensive materials\'\n    a4: \'An NPC talks with a character about a recent adventure they shared\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_3:\n  \'#title\': \'When to contact the Setting department\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'Send both Setting department leads a brief synopsis of the saga idea to see if they approve of the impact on the IC world\'\n    a2: \'Submit any NPCs with mights over 140 to the Setting department for their approval, along with any powerful items involved in the session\'\n    a3: \'See if any other SHs should like to help run the saga or host additional sessions that tie into it\'\n    a4: \'Post notice of the sessions on the forums to poll players for attendance\'\n    a5: \'Run the first session in the saga\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_4:\n  \'#title\': \'Rank the 3 Fs\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'Fun, Freedom, Fairness\'\n    a2: \'Fairness, Freedom, Fun\'\n    a3: \'Fun, Fairness, Freedom\'\n    a4: \'Fairness, Fun, Freedom\'\n    a5: \'Freedom, Fun, Fairness\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_5:\n  \'#title\': Railroading\n  \'#type\': radios\n  \'#options\':\n    a1: Fun\n    a2: Freedom\n    a3: Fairness\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_6:\n  \'#title\': \'Fudging the Numbers\'\n  \'#type\': radios\n  \'#options\':\n    a1: Fun\n    a2: Freedom\n    a3: Fairness\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_7:\n  \'#title\': PVP\n  \'#type\': radios\n  \'#options\':\n    a1: \'Player-vs-player combat\'\n    a2: \'An SH wants to run a sitewide saga\'\n    a3: \'A player has an idea for a sword based on the visuals from an anime he saw\'\n    a4: \'One PC is rolling exceedingly well, out-performing all the others in the session\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_8:\n  \'#title\': \'Session Report Elements\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'The location of the session\'\n    a2: \'Exceptional combat rolls\'\n    a3: \'The impact the PCs had on the situation\'\n    a4: \'The bad guy’s plans\'\n    a5: \'What the NPCs did\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_9:\n  \'#title\': \'Narrative Examples - Railroading\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'You didn’t give enough details about the cave mouth\'\n    a2: \'You made the decision to enter on the players’ behalf\'\n    a3: \'You weren’t clear about what was happening\'\n  \'#options_randomize\': true\n  \'#required\': true\nquestion_10:\n  \'#title\': \'Narrative Examples - All content, no flavor\'\n  \'#type\': radios\n  \'#options\':\n    a1: \'You weren’t clear about what happened\'\n    a2: \'You’re spotlighting the NPC, rather than the player\'\n    a3: \'Your description is all content and no flavor\'\n  \'#