INSERT INTO `node__field_personality` VALUES
('character_sheet',0,60,60,'en',0,'Patient, dry-humoured, protective of travellers and suspicious of anyone who wants to go into the Wood on purpose.','filtered_html'),
('character_sheet',0,63,63,'en',0,'By the book; can be talked down, not bribed.','filtered_html'),
('character_sheet',0,65,65,'en',0,'Gruff, fair; sells rumours for a drink.','filtered_html'),
('character_sheet',0,66,66,'en',0,'Cheerful, nosy, remembers every face.','filtered_html'),
('character_sheet',0,67,67,'en',0,'Haggles for sport; a story for every item.','filtered_html'),
('character_sheet',0,68,68,'en',0,'More bluster than bravery; runs when it turns.','filtered_html'),
('character_sheet',0,69,69,'en',0,'Kind to the sick, sharp with fools.','filtered_html'),
('character_sheet',0,84,84,'en',0,'Blunt, warm once you earn it, and convinced every machine can be fixed if people would just listen.','filtered_html'),
('character_sheet',0,87,87,'en',0,'Procedural, underpaid, likes paperwork.','filtered_html'),
('character_sheet',0,89,89,'en',0,'Neutral; sells drinks, rumours and silence.','filtered_html'),
('character_sheet',0,90,90,'en',0,'Polite, literal, recording everything.','filtered_html'),
('character_sheet',0,91,91,'en',0,'Friendly, opportunistic, half honest.','filtered_html'),
('character_sheet',0,92,92,'en',0,'Loud, greedy, loyal to this weeks pay.','filtered_html'),
('character_sheet',0,93,93,'en',0,'Eager, chatty, offended by bad engines.','filtered_html'),
('character_sheet',0,108,108,'en',0,'Gruff, tired, stubborn, and unable to leave a missing person alone.','filtered_html'),
('character_sheet',0,111,111,'en',0,'Earnest, scared, believes in rules not ghosts.','filtered_html'),
('character_sheet',0,112,112,'en',0,'Calls everyone hon; saw something by the highway.','filtered_html'),
('character_sheet',0,113,113,'en',0,'Quiet, watchful, closes early on certain nights.','filtered_html'),
('character_sheet',0,114,114,'en',0,'Sweet, sharp-eyed, always has what you need.','filtered_html'),
('character_sheet',0,115,115,'en',0,'Says nothing; avoids certain rooms.','filtered_html'),
('character_sheet',0,116,116,'en',0,'Serene, polite, certain the end is near.','filtered_html');
