INSERT INTO `node_revision__field_description` VALUES
('character_sheet',0,60,60,'en',0,'Small, sun-browned and very quiet. A green cloak, a longbow taller than she is, and eyes that never stop moving.','filtered_html'),
('character_sheet',0,63,63,'en',0,'Helm, tabard, spear and a tired stare.','filtered_html'),
('character_sheet',0,65,65,'en',0,'Polishes a mug and hears everything.','filtered_html'),
('character_sheet',0,66,66,'en',0,'Quick feet, full tray, pencil behind an ear.','filtered_html'),
('character_sheet',0,67,67,'en',0,'Spectacles, inky apron, a shop full of odds and ends.','filtered_html'),
('character_sheet',0,68,68,'en',0,'Patched cloak, masked face, rusty blade.','filtered_html'),
('character_sheet',0,69,69,'en',0,'Barefoot, hung with charms, smelling of herbs.','filtered_html'),
('character_sheet',0,84,84,'en',0,'Tall, close-cropped grey hair, a tool belt she never takes off and burn scars on both forearms.','filtered_html'),
('character_sheet',0,87,87,'en',0,'Armoured jumpsuit, mirrored visor, stun baton.','filtered_html'),
('character_sheet',0,89,89,'en',0,'Four arms mixing four drinks at once.','filtered_html'),
('character_sheet',0,90,90,'en',0,'Chrome server unit with a painted smile.','filtered_html'),
('character_sheet',0,91,91,'en',0,'A stall of salvage and a gold-toothed smile.','filtered_html'),
('character_sheet',0,92,92,'en',0,'Scavenged armour and a cybernetic arm.','filtered_html'),
('character_sheet',0,93,93,'en',0,'Oil-stained coverall, tools clipped everywhere.','filtered_html'),
('character_sheet',0,108,108,'en',0,'Heavy-set, grey stubble, a deputy\'s jacket he no longer has the right to wear, and a hound at his heel.','filtered_html'),
('character_sheet',0,111,111,'en',0,'Too-big hat, muddy cruiser, unfired revolver.','filtered_html'),
('character_sheet',0,112,112,'en',0,'Pink uniform and a coffee pot that never empties.','filtered_html'),
('character_sheet',0,113,113,'en',0,'Flannel, old tattoos, salt shells under the bar.','filtered_html'),
('character_sheet',0,114,114,'en',0,'Cardigan, glasses on a chain, chalk and candles in stock.','filtered_html'),
('character_sheet',0,115,115,'en',0,'Stained whites, heavy keys, flickering flashlight.','filtered_html'),
('character_sheet',0,116,116,'en',0,'Hooded robe, ritual knife, a sigil on one palm.','filtered_html');
