INSERT INTO `users_field_data` VALUES
(0,'en','en',NULL,'',NULL,NULL,NULL,0,1795742442,1795742442,0,0,NULL,1),
(1,'en','en',NULL,'admin','$2y$10$LObavnxqWTSSl8GvaaoRtOSBlo3KNKTbYU4jTFlpnVsUsRFMOCuU6','admin@example.com','America/New_York',1,1795742442,1795742693,0,0,'admin@example.com',1);
INSERT INTO `vaxia_chat_post_revision` VALUES
(1,1,1,1795742688,'Welcome','<p><strong>Welcome to your new site!</strong> This is Limbo, the out-of-character room: say hello, ask questions, and chat without a character. Posts here earn no XP.</p>\n<p>To start playing:</p>\n<ol>\n<li>Pick a world: <a href=\"/wiki/eldmoor\">Eldmoor</a> (Fantasy), <a href=\"/wiki/the-meridian-reach\">the Meridian Reach</a> (Science Fiction) or <a href=\"/wiki/hollow-creek\">Hollow Creek</a> (Horror).</li>\n<li>Read <a href=\"/wiki/character-creation\">Character Creation</a>, then make a character and submit it for evaluation.</li>\n<li>Once it\'s approved, post in your world\'s rooms, or ask for a session on the forums.</li>\n</ol>\n<p>Stuck? Ask here. Once you have an approved character, the \"I\'m bored.\" button here suggests a place to play. Please read the <a href=\"/wiki/code-conduct\">Code of Conduct</a> before you post.</p>','filtered_html'),
(2,2,1,1795742688,'The Prancing Stag','A crowded tavern in Thornwick: a roaring hearth, a notice board full of jobs, and a barkeep who hears everything. Where parties form and rumours start.','filtered_html'),
(3,3,1,1795742688,'The Whispering Wood','Ancient trees, paths that move when no one is looking, and lights between the trunks at night. The fae keep their bargains, to the letter.','filtered_html'),
(4,4,1,1795742688,'Ruins of Castle Greymoor','A broken fortress on a hill above the marsh. Its halls are fallen, its cellars are not, and something below still guards the emperor\'s vault.','filtered_html'),
(5,5,1,1795742688,'Port Kessler Promenade','The free port\'s main ring: neon noodle stalls, salvage brokers, a dockside bar, and a view of every ship in the Reach. Jobs, gossip and trouble are all for sale.','filtered_html'),
(6,6,1,1795742688,'Bridge of the Meridian','A freighter\'s cramped bridge: a cracked viewscreen, three crash couches and a navigation computer with opinions. Home, if you can keep her flying.','filtered_html'),
(7,7,1,1795742688,'The Derelict Icarus','A research vessel found adrift past the last gate. Power flickers, the logs end mid-sentence, and the airlocks were opened from the inside.','filtered_html'),
(8,8,1,1795742688,'The Last Light Diner','Chrome, cracked vinyl booths and bottomless coffee. The only place in Hollow Creek open past midnight, and the waitress knows which regulars stopped coming in.','filtered_html'),
(9,9,1,1795742688,'Blackwood Asylum','Closed forty years ago after a fire nobody talks about. The doors are chained from the inside, the patient files are still in the cabinets, and the night nurse\'s bell still rings.','filtered_html'),
(10,10,1,1795742688,'Ravensworth Manor','A gothic house on the hill above town. Portraits whose eyes follow you, locked wings, and a family dinner you may not leave until it is finished.','filtered_html');
